/* HEXA BATTLEGROUNDS setup — PART 65 OF 79. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('battle-bomb-40', 'bomb', 'battle', 'Defuse Duel', 'game', 1, array['duel_pistol','duel_smg']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Blue, Yellow, Black, Yellow.\nSerial number: OM85A8.  LED: BLUE.","game":{"type":"bomb","wires":["blue","yellow","black","yellow"],"serial":"OM85A8","led":"blue"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there is a WHITE wire and the LED is RED, cut the white wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["1"]}]'::jsonb, false, 3, 80, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'blue,yellow,black,yellow · OM85A8 · blue → otherwise → first wire → wire 1', null, 25, 'published'), ('battle-bomb-41', 'bomb', 'battle', 'Defuse Duel', 'game', 2, array['duel_pistol','duel_smg']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Green, Red, Black, Red, Red, Red.\nSerial number: HX19A0.  LED: BLUE.","game":{"type":"bomb","wires":["green","red","black","red","red","red"],"serial":"HX19A0","led":"blue"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If the serial number contains the digit 7, cut the THIRD wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["6"]}]'::jsonb, false, 3, 80, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'green,red,black,red,red,red · HX19A0 · blue → more than one red → last red → wire 6', null, 25, 'published'), ('battle-bomb-42', 'bomb', 'battle', 'Defuse Duel', 'game', 1, array['duel_pistol','duel_smg']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: White, Black, Black, Red, Yellow.\nSerial number: TN51Q9.  LED: RED.","game":{"type":"bomb","wires":["white","black","black","red","yellow"],"serial":"TN51Q9","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there are exactly two BLACK wires, cut the FIRST black wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["2"]}]'::jsonb, false, 3, 80, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'white,black,black,red,yellow · TN51Q9 · red → override: If there are exactly two BLACK wires, cut the FIRST black wire — ignore the manual. → wire 2', null, 25, 'published'), ('battle-bomb-43', 'bomb', 'battle', 'Defuse Duel', 'game', 1, array['duel_pistol','duel_smg']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Black, Black, Black, Red.\nSerial number: OM27Q0.  LED: BLUE.","game":{"type":"bomb","wires":["black","black","black","red"],"serial":"OM27Q0","led":"blue"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If the LED is BLUE and the first wire is YELLOW, cut the LAST wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["2"]}]'::jsonb, false, 3, 80, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'black,black,black,red · OM27Q0 · blue → no yellow → second wire → wire 2', null, 25, 'published'), ('battle-bomb-44', 'bomb', 'battle', 'Defuse Duel', 'game', 2, array['duel_pistol','duel_smg']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Yellow, Black, Yellow, Red, Yellow, Red.\nSerial number: TN40K3.  LED: RED.","game":{"type":"bomb","wires":["yellow","black","yellow","red","yellow","red"],"serial":"TN40K3","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there are no RED wires at all, cut the wire just ABOVE the last one — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["6"]}]'::jsonb, false, 3, 80, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'yellow,black,yellow,red,yellow,red · TN40K3 · red → more than one red → last red → wire 6', null, 25, 'published'), ('battle-bomb-45', 'bomb', 'battle', 'Defuse Duel', 'game', 1, array['duel_pistol','duel_smg']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Red, Yellow, Blue, Red, White.\nSerial number: SR57A7.  LED: RED.","game":{"type":"bomb","wires":["red","yellow","blue","red","white"],"serial":"SR57A7","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there is a WHITE wire and the LED is RED, cut the white wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["5"]}]'::jsonb, false, 3, 80, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'red,yellow,blue,red,white · SR57A7 · red → override: If there is a WHITE wire and the LED is RED, cut the white wire — ignore the manual. → wire 5', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('recovery-bomb-60', 'bomb', 'recovery', 'Bomb Defusal', 'game', 1, array['any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: White, Blue, White, Green, Blue, Blue.\nSerial number: SR17K8.  LED: RED.","game":{"type":"bomb","wires":["white","blue","white","green","blue","blue"],"serial":"SR17K8","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If there is a WHITE wire and the LED is RED, cut the white wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["1"]}]'::jsonb, false, 5, 120, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'white,blue,white,green,blue,blue · SR17K8 · red → override: If there is a WHITE wire and the LED is RED, cut the white wire — ignore the manual. → wire 1', null, 25, 'published'), ('recovery-bomb-61', 'bomb', 'recovery', 'Bomb Defusal', 'game', 1, array['any']::text[], 'A device is ticking. Scout can see it, Decoder holds the bomb manual, Intel has a special order from HQ. Agree on ONE wire and cut it.', '{"scout":{"title":"The device","body":"Wires from the TOP: Blue, White, Black, Yellow, White, Red.\nSerial number: HX96Z8.  LED: RED.","game":{"type":"bomb","wires":["blue","white","black","yellow","white","red"],"serial":"HX96Z8","led":"red"}},"decoder":{"title":"Bomb manual","body":"1. More than one RED wire → cut the LAST red wire.\n2. Otherwise, if the serial number ends in an ODD digit and there is a BLUE wire → cut the FIRST blue wire.\n3. Otherwise, if the LED is GREEN → cut the LAST wire.\n4. Otherwise, if there is no YELLOW wire → cut the SECOND wire.\n5. Otherwise → cut the FIRST wire."},"intel":{"title":"Order from HQ (check first!)","body":"If the serial number contains the digit 7, cut the THIRD wire — ignore the manual."}}'::jsonb, '[{"label":"Wire to cut (number from the top)","accept":["1"]}]'::jsonb, false, 5, 120, 'Intel first: does HQ''s order apply? If not, Decoder walks down the manual from rule 1. Scout describes every wire top to bottom.', 'blue,white,black,yellow,white,red · HX96Z8 · red → otherwise → first wire → wire 1', null, 25, 'published'), ('recovery-bomb-62', 'bomb', 'recovery', 'Bomb Defusal', 'game', 2, array['any']::text[], 'A device is